declare(strict_types=1);
if(!defined('ACADEMY_ROOT')){http_response_code(403);exit;}

// Server-only scenario graphs. No answer key is sent to an unfinished assessment.
function academy_call_catalog(): array
{
    $catalog=[
        'panels'=>['title'=>'Πάνελ προς πώληση','brand'=>'melas','version'=>1,'summary'=>'Ξεχώρισε μια πραγματική ευκαιρία από μια ανεπιβεβαίωτη πληροφορία.'],
        'service'=>['title'=>'Ανάγκη σε φωτοβολταϊκό πάρκο','brand'=>'melas','version'=>1,'summary'=>'Διερεύνησε την ανάγκη χωρίς τεχνικές διαγνώσεις ή μη εγκεκριμένες τιμές.'],
        'discovery'=>['title'=>'Νέα συνεργασία Distillogic','brand'=>'distillogic','version'=>1,'summary'=>'Μάθε τη διαδικασία, τους υπεύθυνους και όσα ακόμη δεν έχουν αποφασιστεί.'],
        'refusal'=>['title'=>'Δεν είναι κάθε επαφή qualified lead','brand'=>'melas','version'=>1,'summary'=>'Χειρίσου ελλιπή στοιχεία και μια σαφή άρνηση επικοινωνίας.'],
        'proposal'=>['title'=>'Πίεση για άμεση προσφορά','brand'=>'distillogic','version'=>1,'summary'=>'Συμφώνησε επόμενο βήμα χωρίς να παρακάμψεις εμπορική έγκριση.'],
    ];
    foreach($catalog as &$item){$item['version']=2;$item['accepted_versions']=[1,2];}
    unset($item);return $catalog;
}
function academy_call_option(string $text,string $reply,int $points,string $next,array $reveals=[],bool $critical=false): array
{
    return compact('text','reply','points','next','reveals','critical');
}
function academy_call_field(string $label,string $answer,string $type='text',array $options=[],bool $critical=false): array
{
    return compact('label','answer','type','options','critical');
}
